SELECT
	COUNT(SSA.ORDER_NO) as MSQ,
	IFNULL(SUM(SSA.PAYMENT_AMOUNT),0) as PAYMENT_AMOUNT,
	IFNULL(SUM(SSA.ORDER_AMOUNT),0) as ORDER_AMOUNT
FROM SHOP_SALES_API SSA
WHERE SSA.SHOP_TYPE IN #{type}
	AND SSA.SHOP_ID IN #{shopid}
	AND PAID_DATE BETWEEN DATE_FORMAT(ADDDATE(SUBDATE(NOW(), INTERVAL 1 MONTH),INTERVAL 1 DAY),'%Y%m%d') AND DATE_FORMAT(NOW(),'%Y%m%d');

SELECT IFNULL(SUM(SSA.SETTLE_ESTIMATE_AMOUNT),0) AS MSA, COUNT(SSA.SETTLE_ESTIMATE_AMOUNT) AS COUNT_MSA FROM SHOP_SALES_API SSA WHERE SSA.SHOP_TYPE =#{SHOP_TYPE} AND SSA.SHOP_ID = #{SHOP_ID}
AND SSA.PAID_DATE BETWEEN DATE_FORMAT(ADDDATE(SUBDATE(NOW(), INTERVAL 1 MONTH),INTERVAL 1 DAY),'%Y%m%d') AND DATE_FORMAT(NOW(),'%Y%m%d')
AND SSA.SETTLE_ESTIMATE_DATE BETWEEN DATE_FORMAT(ADDDATE(SUBDATE(NOW(), INTERVAL 1 MONTH),INTERVAL 1 DAY),'%Y%m%d') AND DATE_FORMAT(NOW(),'%Y%m%d')

mapper.update:
UPDATE
	MONEYBANK_SUB_CHECK
SET
	sub_complete = 'Y',
	final_confirm_admin = #{userId}
WHERE mbid = #{mbid}
